            error?: string;
            /** @description `tool_result` only: the process status of a shell call. A pointer, because a tool that is not a shell reports no code at all — read absence as "no code was reported", never as "exited 0". */
            exitCode?: number;
            /** @description `git_commit` only: how many files the commit touched. */
            files?: number;
