            model?: string;
            /** @description `tool_result`, the `git_*` kinds and `gh_action`: did it succeed? A pointer, because absence means the producer did not say — read it as unknown, never as success. */
            ok?: boolean;
            /**
             * @description `turn_ended` and `run_settled`: how it ended. `cancelled` is deliberately not a `failure`: the work was taken away rather than going wrong, and a run someone stopped on purpose must not be reported as broken.
             * @enum {string}
             */
            outcome?: "success" | "failure" | "cancelled";
