            branch?: string;
            command?: string;
            /** @description Id of the cycle this line belongs to — the accordion section key. */
            cycleId: string;
            /**
             * Format: int64
             * @description 1-based position of that cycle in the run, so the console can label a section without holding the whole cycle list.
             */
            cycleIndex: number;
            /** @description Kind of that cycle (coding | conflict | fix | validation) — the section label. */
            cycleKind: string;
            /**
             * Format: int64
             * @description `tool_result` only: how long the call took, measured by the runner between the call and its outcome, so it includes model turnaround.
             */
            durationMs?: number;
            /**
             * @description Who produced the line. The runner stamps `subagent` only on lines forwarded from inside a Task tool call; everything else is the main agent.
             * @enum {string}
             */
            emitter: "main" | "subagent";
            /** @description Which subagent, for the cycles that fan out to several at once — the id of the fan-out tool call, stable for that subagent's whole life. Absent on main-agent lines. */
            emitterId?: string;
            /** @description The description the main agent gave that subagent ("Implement todo-api service (issue */
            emitterLabel?: string;
            error?: string;
