    "stream-run-progress": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Project name (DNS-label slug) */
                projectName: string;
                /** @description Milestone run id */
                runId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description ONE SSE stream stitching every cycle of the run: a `cycle` frame per cycle record (client upserts by id) and a `line` frame per agent-log entry, each line carrying the id of the cycle that produced it so the console can render one accordion section per cycle. Each line also carries an `emitter` chip — `main` for the run's main agent, `subagent` for work it fanned out with the Task tool. One `data:` JSON frame per event (a RunProgressEvent discriminated by `type`), each stamped `id: <seq>`; `: keep-alive` comments pace idle waits. ONLY a terminal run settles the stream: a terminal run streams its whole history then ends with a `done` frame, `data: [DONE]`, and a server close, while a live run stays open indefinitely. Reconnects are idempotent — the client upserts cycles by id and dedups lines by cycleId+seq. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": components["schemas"]["RunProgressEvent"];
                };
            };
            /** @description Error */
            default: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
